import { Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { Usuario } from '../models/usuario.model';
import { firstValueFrom } from 'rxjs';

@Injectable({
  providedIn: 'any',
})
export class UsuarioService extends SuperService<Usuario> {
  protected override model = 'usuarios';

  protected override columns: (keyof Usuario)[] = [
    'email',
    'password',
    'nombre',
    'apellido_paterno',
    'apellido_materno',
  ];

  constructor(injector: Injector) {
    super(injector);
  }

  public async usuariosEjecutivosCobranza(){
    return (await firstValueFrom(this.api.get<Usuario[]>('api/usuarios_ejecutivos', {}, false))).data??[]
  }
}
